<?php get_header(); ?>
<main class="single-wrap"><div class="container single-grid"><div><article <?php post_class('single-post'); ?>><header class="single-header"><span class="eyebrow"><?php $cats=get_the_category();if($cats)echo esc_html($cats[0]->name); ?></span><h1 class="single-title"><?php the_title(); ?></h1><div class="single-meta"><span>By <?php the_author(); ?></span><span><?php echo esc_html(get_the_date('F j, Y')); ?></span><span><?php echo esc_html(max(1,ceil(str_word_count(wp_strip_all_tags(get_the_content()))/200))); ?> min read</span></div></header><?php if(has_post_thumbnail()): ?><div class="featured"><?php the_post_thumbnail('full'); ?></div><?php endif; ?><div class="entry-content"><?php the_content(); ?></div><div class="single-tags"><?php the_tags('<strong>Topics:</strong> ', ' ', ''); ?></div><?php if(function_exists('get_previous_post')): ?><nav class="post-nav"><?php $prev=get_previous_post();$next=get_next_post(); if($prev): ?><a href="<?php echo esc_url(get_permalink($prev)); ?>"><small>← Previous</small><?php echo esc_html(get_the_title($prev)); ?></a><?php endif;if($next): ?><a href="<?php echo esc_url(get_permalink($next)); ?>"><small>Next →</small><?php echo esc_html(get_the_title($next)); ?></a><?php endif; ?></nav><?php endif; ?><?php comments_template(); ?></article></div><aside class="single-sidebar"><?php get_sidebar(); ?></aside></div></main><?php get_footer(); ?>